ins.on=global.on_unit_count; global.on_unit_count+=1
if !global.player_wow[player]{ins.unit_id=4}else{ins.unit_id=105}
with(ins){sk_unit_skil_to(unit_id)}
ds_list_add(global.on_unit, string(ins.on))
