for(i=0; i!=4; i+=1)
{
    if !global.player_wow[player]
    {
        ins=instance_create(x, y+sprite_get_bbox_bottom(global.unit_id_spr[4, 0])+sprite_get_bbox_bottom(global.unit_id_spr[8, 0]), obj_unit)
        ins.player=player
        ins.unit_id=8
        ins.on=global.on_unit_count; global.on_unit_count+=1
        with(ins){sk_unit_skil_to(unit_id)}
        ds_list_add(global.on_unit, string(ins.on))
        ds_list_add(global.on_unit, ins)
    }
    else
    {
        ins=instance_create(x, y+sprite_get_bbox_bottom(global.unit_id_spr[105, 0])+sprite_get_bbox_bottom(global.unit_id_spr[104, 0]), obj_unit)
        ins.player=player
        ins.unit_id=104
        ins.on=global.on_unit_count; global.on_unit_count+=1
        with(ins){sk_unit_skil_to(unit_id)}
        ds_list_add(global.on_unit, string(ins.on))
        ds_list_add(global.on_unit, ins)
    }
}

if global.player_control=player
{
    view_xview=min(room_width-641, max(0, x-view_wview/2))
    view_yview=min(room_height-481, max(0, y-view_hview/2))
